        ServerPool pool = new ServerPool(Arrays.asList("A", "B", "C"));

        for (int i = 1; i <= 3; i++) {
            System.out.println("Request " + i + " -> " + pool.nextServer());
        }

        pool.markUnhealthy("B");
        System.out.println("Server B failed its health check, marked unhealthy");

        for (int i = 4; i <= 6; i++) {
            System.out.println("Request " + i + " -> " + pool.nextServer());
        }

        pool.markHealthy("B");
        System.out.println("Server B recovered, marked healthy again");

        for (int i = 7; i <= 9; i++) {
            System.out.println("Request " + i + " -> " + pool.nextServer());
        }
    }
}

// A server pool that only ever routes to healthy servers, skipping any server
// currently failing its health check and resuming it automatically once it recovers.
class ServerPool {
    private final List<String> servers;
    private final Map<String, Boolean> healthy = new HashMap<>();
    private int currentIndex = 0;

    ServerPool(List<String> servers) {
        this.servers = servers;
        for (String server : servers) healthy.put(server, true);
    }

    void markUnhealthy(String server) { healthy.put(server, false); }
    void markHealthy(String server) { healthy.put(server, true); }

    String nextServer() {
        for (int attempts = 0; attempts < servers.size(); attempts++) {
            String candidate = servers.get(currentIndex);
            currentIndex = (currentIndex + 1) % servers.size();
            if (healthy.get(candidate)) {
                return candidate;
            }
        }
        return "NO HEALTHY SERVERS";
    }
}

