class ServerPool:
    # A server pool that only ever routes to healthy servers, skipping any server
    # currently failing its health check and resuming it automatically once it recovers.
    def __init__(self, servers):
        self.servers = servers
        self.healthy = {server: True for server in servers}
        self.current_index = 0

    def mark_unhealthy(self, server):
        self.healthy[server] = False

    def mark_healthy(self, server):
        self.healthy[server] = True

    def next_server(self):
        for _ in range(len(self.servers)):
            candidate = self.servers[self.current_index]
            self.current_index = (self.current_index + 1) % len(self.servers)
            if self.healthy[candidate]:
                return candidate
        return "NO HEALTHY SERVERS"


def main():
    pool = ServerPool(["A", "B", "C"])

    for i in range(1, 4):
        print(f"Request {i} -> {pool.next_server()}")

    pool.mark_unhealthy("B")
    print("Server B failed its health check, marked unhealthy")

    for i in range(4, 7):
        print(f"Request {i} -> {pool.next_server()}")

    pool.mark_healthy("B")
    print("Server B recovered, marked healthy again")

    for i in range(7, 10):
        print(f"Request {i} -> {pool.next_server()}")


if __name__ == "__main__":
    main()

