#include <iostream>
#include <vector>
#include <map>
#include <string>
using namespace std;

// A server pool that only ever routes to healthy servers, skipping any server
// currently failing its health check and resuming it automatically once it recovers.
class ServerPool {
public:
    ServerPool(const vector<string>& servers) : servers(servers), currentIndex(0) {
        for (const auto& server : servers) healthy[server] = true;
    }

    void markUnhealthy(const string& server) { healthy[server] = false; }
    void markHealthy(const string& server) { healthy[server] = true; }

    string nextServer() {
        for (size_t attempts = 0; attempts < servers.size(); attempts++) {
            string candidate = servers[currentIndex];
            currentIndex = (currentIndex + 1) % servers.size();
            if (healthy[candidate]) {
                return candidate;
            }
        }
        return "NO HEALTHY SERVERS";
    }

private:
    vector<string> servers;
    map<string, bool> healthy;
    size_t currentIndex;
};

int main() {
    ServerPool pool({"A", "B", "C"});

    for (int i = 1; i <= 3; i++) {
        cout << "Request " << i << " -> " << pool.nextServer() << endl;
    }

    pool.markUnhealthy("B");
    cout << "Server B failed its health check, marked unhealthy" << endl;

    for (int i = 4; i <= 6; i++) {
        cout << "Request " << i << " -> " << pool.nextServer() << endl;
    }

    pool.markHealthy("B");
    cout << "Server B recovered, marked healthy again" << endl;

    for (int i = 7; i <= 9; i++) {
        cout << "Request " << i << " -> " << pool.nextServer() << endl;
    }

    return 0;
}
